<?php $title='News'; require 'config/config.php'; require_login(); $news=$pdo->query('SELECT * FROM news ORDER BY published_at DESC')->fetchAll(); require 'includes/header.php'; ?><section class="section"><div class="container"><h1>Latest News</h1><div class="cards"><?php foreach($news as $n): ?><article class="card"><img src="assets/images/<?=e($n['image'])?>" alt=""><div class="cardbody"><span class="date"><?=e(date('M d, Y',strtotime($n['published_at'])))?></span><h2><?=e($n['title'])?></h2><p class="muted"><?=e($n['excerpt'])?></p></div></article><?php endforeach; ?></div></div></section><?php require 'includes/footer.php'; ?>
